function scenarios(){const s=state.scenario,v=E.scenario(s);return head('Interacting exposure','Cumulative risk, made concrete','Test a shared cash consequence. Ordinal risk scores are not added together; linked exposures are assessed through common drivers.')+
 `<div class="notice amber">Illustrative sensitivity only. These assumptions are not Operator forecasts, liquidity, production guidance or commodity economics. Cash contribution is a user-defined amount per boe; tax, hedging, working capital and recovery timing are excluded.</div><div class="grid half"><section class="panel"><div class="panel-head"><div><h2>Combined downside assumptions</h2><p>All amounts in USD · cash and capex in millions</p></div></div><div class="panel-body"><form id="scenario-form" class="form-grid"><label class="full">Scenario name<input name="name" value="${esc(s.name)}" required maxlength="160"></label>${[['production','Incremental production unavailable (boe/day)',s.production,1000000],['days','Outage duration (days)',s.days,3660],['margin','Lost cash contribution ($/boe)',s.margin,1000],['extraCapex','Additional cash expenditure ($m)',s.extraCapex,100000],['availableCash','Starting available cash ($m)',s.availableCash,100000],['buffer','Minimum planning cash buffer ($m)',s.buffer,100000]].map(([name,label,value,max])=>`<label>${label}<input type="number" name="${name}" value="${value}" min="0" max="${max}" step="${name==='days'||name==='production'?'1':'0.1'}" required></label>`).join('')}<div class="full"><button class="button primary" type="submit">Recalculate & save</button></div></form></div></section><div><section class="scenario-output"><div class="eyebrow" style="color:#e6b493">Illustrative cash sensitivity</div><h2>${esc(s.name)}</h2><div class="scenario-value">${money(v.draw)}</div><p>Combined incremental cash impact</p><div class="scenario-breakdown"><span>Lost operating cash contribution</span><strong>${money(v.loss)}</strong></div><div class="scenario-breakdown"><span>Additional cash expenditure</span><strong>${money(s.extraCapex)}</strong></div><div class="scenario-breakdown"><span>Remaining available cash</span><strong>${money(v.remaining)}</strong></div><div class="scenario-breakdown"><span>Headroom / (shortfall) to buffer</span><strong>${money(v.bufferGap)}</strong></div>${badge(v.bufferGap<0?'Below illustrative planning buffer':'Above illustrative planning buffer',v.bufferGap<0?'red':'green')}<p style="margin-top:16px">Decision lens: sequence discretionary expenditure, challenge outage recovery and confirm contingency funding before additional commitments.</p></section><div class="notice section-gap">Use production loss only once for the affected barrels. Additional expenditure must exclude costs already included in the cash-contribution assumption. This is a deterministic stress, not a probability-weighted loss estimate.</div></div></div><div class="section-title"><h2>Shared drivers to challenge</h2></div><div class="grid three"><section class="panel source-card"><h3>Outage + growth project</h3><p>A processing outage can reduce existing production and defer a new tie-back. Test the common infrastructure dependency.</p>${linkedRisks(['R02','R05','R04'])}</section><section class="panel source-card"><h3>Integration + critical people</h3><p>Change demand and an absent specialist can weaken assurance across several assets. Test capacity and deputy cover together.</p>${linkedRisks(['R03','R07','R01'])}</section><section class="panel source-card"><h3>Cyber + continuity</h3><p>A system incident can disrupt operations, reporting and recovery simultaneously. Test restoration and incident leadership as one scenario.</p>${linkedRisks(['R08','R14','R06'])}</section></div>`;}
function reportDefault(m){return {what:'Asset Bravo has a reliability exposure with a shared export dependency affecting Asset Alpha. Independent barrier evidence challenges the positive maintenance closure signal. All positions are synthetic examples.',so:'Operational interruption, integration capacity and capital demand can combine to weaken cash generation and delivery confidence. Current scores and control assessments require owner validation.',now:'Request the COO to validate the combined asset recovery and barrier assurance plan by 23 October; Finance to reconcile the downside cash bridge before the next discretionary capital gate.',decisions:'1. Commission independent verification of the affected barriers; accountable: COO; due: 23 October.\n2. Require a staged recovery plan with evidence at each gate; accountable: Asset Manager; due: 28 October.\n3. Re-sequence discretionary capital if the cash buffer is breached; accountable: CFO; due: next investment gate. No operational authorisation is conferred by this report.',prepared:'Operator risk team',reviewer:'',reviewDate:'',status:'Draft'};}
function reportData(){const saved=state.snapshots.find(s=>s.id===snapshotId);if(saved)return saved;const cutoff=E.monthEnd(month)<today()?E.monthEnd(month):today();return {month,cutoff,created:new Date().toISOString(),revision:0,sources:E.clone(SEED.sources),risks:E.clone(state.risks),controls:E.clone(state.controls),actions:E.clone(state.actions),events:E.clone(state.events),oras:E.clone(state.oras),findings:E.clone(state.findings),indicatorHistory:E.clone(state.indicatorHistory),imports:E.clone(state.imports),reports:E.clone(state.reports),deviationHistory:E.clone(state.deviationHistory),matrixAssessments:E.clone(state.matrixAssessments),aggregates:E.clone(state.aggregates),triangulations:E.clone(state.triangulations),indicators:E.clone(state.indicators),scenario:E.clone(state.scenario),governance:E.clone(state.governance),board:E.clone(state.board[month]||reportDefault(month)),snapshots:[],contextDate:SEED.contextDate,reconstructed:month<today().slice(0,7)};}
