function setImportTable(){drop.staged=[];drop.error='';try{if(drop.sheets){drop.table=RCC_IMPORT.table(drop.sheets[drop.sheet].matrix,drop.header);}else if(drop.json!==null){drop.table=RCC_IMPORT.jsonTable(drop.json,drop.type);}else if(drop.matrix){drop.table=RCC_IMPORT.table(drop.matrix,1);}drop.mapping=drop.table?RCC_IMPORT.guess(drop.table.headers,drop.type):{};}catch(e){drop.table=null;drop.error=e.message;}render();}
async function readDrop(file){if(!file||drop.busy)return;if(file.size>15000000){drop.error='File exceeds 15 MB. Export a smaller data range.';render();return;}drop={...drop,filename:file.name,busy:true,error:'',table:null,staged:[],sheets:null,matrix:null,json:null,pdf:null,reportNote:''};view='imports';render();try{const ext=file.name.split('.').pop().toLowerCase();if(ext==='xlsx'){drop.sheets=await RCC_IMPORT.readXLSX(await file.arrayBuffer());drop.sheet=0;drop.header=1;}else if(['csv','tsv'].includes(ext)){drop.matrix=RCC_IMPORT.parseCSV(await file.text());}else if(ext==='json'){drop.json=JSON.parse(await file.text());}else if(ext==='pdf'){const pdfjs=await import('./vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='vendor/pdf.worker.min.mjs';const task=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true});const pdf=await task.promise;if(pdf.numPages>100){await pdf.destroy();throw Error('PDF exceeds 100 pages. Extract the relevant report section before importing.');}let text='';for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n);const content=await page.getTextContent();text+='[Page '+n+']\n'+content.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('')+'\n\n';}drop.pages=pdf.numPages;await pdf.destroy();if(text.replace(/\[Page \d+\]/g,'').trim().length<30)throw Error('No usable text found. A scanned PDF needs OCR or a structured CSV/Excel export.');drop.pdf=text.slice(0,120000);if(text.length>120000)drop.error='The first 120,000 characters are available for review. Refer to the original for the complete report.';}else throw Error('Use .xlsx, .csv, .tsv, .json or a text-based .pdf. Legacy .xls files must be saved as .xlsx or CSV.');drop.busy=false;if(drop.pdf!==null)render();else setImportTable();}catch(e){drop.busy=false;drop.error=e.message;render();}}
function stageDrop(){try{drop.error='';drop.staged=RCC_IMPORT.stage(drop.table.rows,drop.mapping,drop.type,state,{risk:drop.risk,at:today(),instant:new Date().toISOString()},drop.filename,drop.mode);render();}catch(e){drop.error=e.message;render();}}
function commitDrop(){try{const candidate=RCC_IMPORT.merge(state,drop.type,drop.staged,new Date().toISOString(),drop.filename);candidate.audit.unshift({at:new Date().toISOString(),text:'Imported '+drop.staged.length+' '+drop.type+' records from '+drop.filename});candidate.audit=candidate.audit.slice(0,100);E.validate(candidate);localStorage.setItem(KEY,JSON.stringify(candidate));lastImport=E.clone(state);state=candidate;snapshotId='';drop.staged=[];drop.table=null;drop.sheets=null;drop.matrix=null;drop.json=null;drop.error='';storageOK=true;$('#save-status').textContent='Saved on this browser';toast('Imported successfully. Saved board snapshots remain unchanged.');render();}catch(e){drop.error='Import not applied: '+e.message;render();}}
function undoImport(){if(!lastImport)return;try{const restored=E.clone(lastImport);restored.audit.unshift({at:new Date().toISOString(),text:'Undid last data import'});localStorage.setItem(KEY,JSON.stringify(restored));state=restored;lastImport=null;snapshotId='';toast('Last import undone.');render();}catch(e){toast('Undo could not be saved. Export a backup.');}}
function saveReport(){const note=$('#report-note').value.trim();if(!note){toast('Add your reviewed note and page references first.');return;}if((state.reports||[]).length>=50){toast('50 evidence extracts reached. Export an archive before adding more.');return;}const candidate=E.clone(state);candidate.reports.push({id:'PDF_'+crypto.randomUUID(),file:drop.filename,text:drop.pdf,at:new Date().toISOString(),risk:drop.risk,note});candidate.imports.unshift({at:new Date().toISOString(),file:drop.filename,type:'PDF evidence',count:1,added:1,updated:0,historical:0});candidate.imports=candidate.imports.slice(0,100);try{E.validate(candidate);localStorage.setItem(KEY,JSON.stringify(candidate));lastImport=E.clone(state);state=candidate;drop.pdf=null;toast('Reviewed extract saved. Original PDF remains with you.');render();}catch(e){drop.error='Evidence not saved: '+e.message;render();}}
