function odBoardHTML(s,day){const a=s.odEvaluation||(s.revision?null:odEvaluation(s,odInstant(day,s)));if(!a)return '<p class="small-text muted">DEMO-DEVIATION governance evaluation was not captured in this older snapshot. No retrospective compliance judgement is asserted.</p>';return `<section class="${s.revision===undefined?'panel section-gap':''}"><div class="${s.revision===undefined?'panel-body':''}"><h3>Operational deviations · DEMO-DEVIATION</h3><p class="small-text">${esc(a.rule)} · evaluated ${timeLabel(a.at)}. ${a.active} active deviations; ${a.clockBreaches} initial-decision / 72-hour exceptions; ${a.clockUnknown} clock bases missing or unconfirmed; ${a.expiry} missing / passed expiries; ${a.exceptionCases} cases with governance evidence gaps. ${a.recurringOverdue.length} repeating checks are overdue or have no next due time.</p><p class="tiny muted">Approval is governed by the abnormal operating risk and the source Risk Assessment Matrices Procedure. Cyber colour bands do not determine operational approvers. This view records source evidence; it neither authorises continued operation nor replaces Synergi.</p><div class="table-wrap"><table><thead><tr><th>Deviation / driving risk</th><th>Decision and expiry position</th><th>Evidence gaps / action for accountable owner</th></tr></thead><tbody>${a.cases.slice(0,20).map(x=>`<tr><td>${esc(x.id)} · ${esc(x.title)}<small>${esc(x.type)} · ${esc(x.hub)} · ${esc(x.risk)}<br>Abnormal risk: ${esc(x.abnormalRisk)}</small></td><td>${esc(x.workflow)}<small>${esc(x.clock)}${x.deadline?'<br>Initial period ends '+timeLabel(x.deadline):''}<br>Expiry ${fmt(x.expires)}</small></td><td>${x.issues.map(i=>esc(i.text)).join('<br>')}</td></tr>`).join('')||'<tr><td colspan="3">No governance exceptions identified from the loaded records. This does not establish completeness or compliance.</td></tr>'}</tbody></table></div>${a.cases.length>20?'<p class="tiny muted">Showing the first 20 exception cases, with timed notification, initial-decision and expiry exceptions first. This review order is not a risk ranking. The deviation register contains the complete list.</p>':''}<h3>Cumulative-risk escalation and human controls</h3><div class="table-wrap"><table><thead><tr><th>Interacting cases</th><th>Connection / review trigger</th><th>Standalone assessment</th></tr></thead><tbody>${a.clusters.map(c=>`<tr><td>${esc(c.hub)}<small>${c.ids.map(esc).join(', ')}</small></td><td>${c.reasons.map(esc).join(', ')}<small>Check shared controls, root causes, external activities, risk transfer and human workload.</small></td><td>${c.saraConsider?'Consider a separate cumulative SARA (three or more interacting deviations or complexity).':'Assess the interaction in the ORA or justify a separate assessment.'}<small>${c.saraRefs.length?'Recorded references: '+c.saraRefs.map(esc).join(', '):'No standalone SARA reference recorded.'}</small></td></tr>`).join('')||'<tr><td colspan="3">No connected group identified in the loaded data. Missing linkage, location or system information limits this check.</td></tr>'}</tbody></table></div>${a.recurringOverdue.length?`<h3>Repeating control checks requiring attention</h3><p class="small-text">${a.recurringOverdue.map(x=>`${esc(x.id)} (${esc(x.actionType)}), ${esc(x.deviationId)}: ${x.nextRepeatAt?timeLabel(x.nextRepeatAt):'next check not recorded'}`).join('; ')}.</p>`:''}</div></section>`;}
