function operatingBrief(){const principles=[
 ['Integrated','Links objectives, asset exposure, controls and the forward plan to management and board decisions.'],
 ['Structured and comprehensive','Uses a consistent risk–control–evidence–action review across strategic, financial and operational exposure.'],
 ['Customised','Reflects Operator’s portfolio and illustrative procedures; wider appetite, thresholds and approval criteria still need company validation.'],
 ['Inclusive','Supports owner, operator, technical specialist and independent reviewer challenge; record whose views informed the judgement.'],
 ['Dynamic','Shows changing indicators, deviations and upcoming activities; refresh after material change as well as monthly.'],
 ['Best available information','Retains source references, dates and unknowns; triangulate ORA, ICP, process safety and control-test evidence before deciding.'],
 ['Human and cultural factors','Prompts review of competence, scarce skills, workload and shared human controls; encourage challenge and reporting of bad news.'],
 ['Continual improvement','Uses monthly comparisons, verification and lessons from events to improve controls and the review process.']
 ];return `<section class="panel" id="operating-brief"><div class="panel-head"><div><h2>How to use the Risk Control Centre</h2><p>A brief for risk owners, asset teams and leadership</p></div></div><div class="panel-body"><p><strong>Purpose:</strong> create and protect value by making uncertainty around Operator’s objectives visible, supporting informed choices about operating reliability, resource commitments and resilience.</p><ol class="guide"><li><strong>Set the basis.</strong> Agree scope, objectives, owners and approved risk criteria. Replace illustrative records and confirm the controlled procedures.</li><li><strong>Load and check evidence.</strong> Import source exports through Data drop &amp; review. Check IDs, links, dates and completeness. Synergi imports require field mapping; a direct connection is not configured.</li><li><strong>Challenge the exposure.</strong> Risk owners and relevant specialists assess controls, action maturity, KRIs and cumulative interactions alongside the next 90 days of activity. A completed action does not prove an effective control or automatically reduce risk.</li><li><strong>Decide and follow through.</strong> Compare exposure with approved appetite; record treatment, accountable owner, due date and any escalation or acceptance through the proper authority. Consider opportunities and trade-offs alongside downside.</li><li><strong>Review and report monthly.</strong> The risk lead coordinates asset/function updates and executive challenge. Explain what changed, why it matters and the decision needed. Record preparer/reviewer, freeze the monthly revision, export the board output and back up the data. Track decisions and verify results next cycle.</li></ol><p class="small-text"><strong>Between reviews:</strong> escalate material control failures, incidents, breached limits or changing conditions immediately through established channels. The monthly cycle must not delay action.</p></div></section><section class="panel section-gap" id="iso31000-brief"><div class="panel-head"><div><h2>How it supports ISO 31000:2018</h2><p>Design mapping to the eight principles · effectiveness depends on how people use it</p></div></div><div class="table-wrap"><table><thead><tr><th>Principle</th><th>Application in this centre</th></tr></thead><tbody>${principles.map(([p,a])=>`<tr><td><strong>${p}</strong></td><td>${a}</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><p class="small-text"><strong>Process:</strong> establish scope, context and criteria; identify, analyse and evaluate risk; select treatment; monitor and review. Consult throughout and record/report the reasoning. Leadership must embed this in governance, resource it and evaluate its performance.</p><p class="small-text muted">This mapping describes intended support, not verified conformity. ISO 31000 provides guidance and is not a certifiable standard. Source-system approvals remain authoritative; the centre does not authorise operation. Working data is saved on this browser/device, with no shared corporate database or automatic circulation.</p><p class="tiny muted">References checked 17 October 2026: <a href="https://www.iso.org/standard/31000" target="_blank" rel="noopener noreferrer">ISO 31000:2018 overview ↗</a> · <a href="https://www.iso.org/news/ref2263.html" target="_blank" rel="noopener noreferrer">ISO guidance on integration and leadership ↗</a>. Practical application above is the model’s interpretation.</p></div></section>`;}
function basis(){return head('Basis & operating guide','Using the centre','Independent demonstration criteria and a practical review cycle.',`<button class="button" id="import-backup">Import JSON backup</button><button class="button primary" id="export-backup">Export JSON backup</button>`)+operatingBrief()+`<div class="notice">This version uses a new generic 5×5 framework. Earlier 8×8 backups and assessments are not automatically converted. Scores, cutoffs, review frequencies and decision routes are illustrative. Review the 5×5 definitions before creating or importing assessments.</div>`+panel('Reporting audiences','One evidence base; different decision rights',audienceGuide());}

function impactField(label,name,value){return `<label>${label}<select name="${name}">${[5,4,3,2,1].map(i=>`<option value="${i}" ${Number(value)===i?'selected':''}>${E.impact(i)} (${i})</option>`).join('')}</select></label>`;}
function cyberSummaryHTML(s,previous){const c=E.cyberSummary(s),p=previous?E.cyberSummary(previous):null;const change=p&&p.elevated.length?((p.elevated.length-c.elevated.length)/p.elevated.length*100):null;return `<h3>Cyber aggregation · Generic cyber guidance</h3><p class="small-text">${c.list.length} active cyber risk records; ${c.elevated.length} Critical / High; ${c.critical.length} with Impact 5; ${c.designated.length} linked to a designated critical service. ${c.acceptance.length} acceptance records have missing sign-off evidence.</p><p class="small-text"><strong>Annual Loss Expectancy (GBP): ${c.quantified.length===0?'Not quantified':c.quantified.length===c.elevated.length?'£'+num(c.total):'Partial £'+num(c.total)}</strong> · ${c.quantified.length} of ${c.elevated.length} elevated risks quantified. ${c.quantified.length<c.elevated.length?'The aggregate is incomplete; do not treat a missing estimate as zero.':''} Frequency × loss-per-event uses separate annual assumptions, never the 1–5 likelihood score. Resolve overlaps and common-event double counting before using the aggregate for investment decisions.</p><p class="small-text">Critical / High count reduction: ${change===null?'No valid prior-month denominator':num(change)+'%'}. This count measure does not, by itself, establish control effectiveness.</p><div class="table-wrap"><table><thead><tr><th>Top 5 cyber risks</th><th>Residual / treatment</th><th>Critical service / sign-off</th></tr></thead><tbody>${[...c.list].sort((a,b)=>b.ri-a.ri||b.rl-a.rl||a.id.localeCompare(b.id)).slice(0,5).map(r=>`<tr><td>${esc(r.id)} · ${esc(r.title)}<small>${esc(r.owner)}</small></td><td>${r.ri}×${r.rl} · ${E.band(r)}<small>${esc(r.treatment)} · review ${fmt(r.review)}</small></td><td>${esc(r.service)} · ${esc(r.serviceRef||'Register reference not recorded')}<small>Owner sign-off ${esc(r.acceptor||'not recorded')} · senior approval ${esc(r.seniorApprover||'not recorded')}</small></td></tr>`).join('')||'<tr><td colspan="3">No cyber assessments recorded.</td></tr>'}</tbody></table></div>`;}
function cyber(){return head('Generic demonstration criteria','Cyber governance','Use the same illustrative 5×5 screening framework while retaining specialist evidence and accountability.',`<button class="button primary" data-edit-risk="new">+ Add assessment</button>`)+`<div class="notice">Cyber likelihood ratings are ordinal judgements for a stated planning horizon; they are not annual event frequencies. Financial loss estimates require separate evidence. No company cyber standard is represented.</div><div class="grid half">${panel('Cyber screening matrix','Generic 5×5',`<div class="panel-body">${heatmap(true)}</div>`)}${panel('Evidence before acceptance','Illustrative management prompts',`<div class="panel-body"><p>Confirm service criticality, recovery dependencies, access controls and restoration tests. Assign an accountable owner and record uncertainty.</p><p>Critical or High exposure needs management escalation and a treatment plan. Actual acceptance and escalation rights must come from the operator’s approved framework.</p></div>`)}</div>${cyberSummaryHTML(state,E.latestPrior(state.snapshots,today().slice(0,7)))}`;}

function openDialog(html,submit){$('#editor-content').innerHTML=html;$('#edit-form').onsubmit=e=>{e.preventDefault();try{submit(new FormData(e.target));}catch(err){toast(err.message);}};$('#editor').showModal();}
